namespace HakutaiKagami.Core.Contracts;
public sealed partial class WorldSession
{
    static bool ReleaseEventInput(CompanionAction action)=>action is CompanionAction.LordReleaseApproved or CompanionAction.LordReleaseRefused or CompanionAction.LordReleaseReceived or CompanionAction.LordRefusalReceived;
    public CompanionCard[] CompanionView(){lock(gate)return PersonalCompanions.View(state);}
    public CommandResult ManageCompanion(CompanionInput input,EntityId actor,long revision)
    {lock(gate){if(ReleaseEventInput(input.Action)||actor!=state.PlayerControl||!EntityId.IsValid(input.Id.Value))return new(ResultCode.NotAvailable,input.Id,state.CommitSequence,"本人の協力相談ではありません");var old=state.Companions?.Orders.SingleOrDefault(q=>q.Input.Id==input.Id);if(old!=null)return new(old.Input==input?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,input.Id,state.CommitSequence,"相談済みです");if(FactionStances.OtherIdUsed(state,input.Id,includeCompanions:false)||FactionStances.OwnIdUsed(state,input.Id))return new(ResultCode.IdPayloadConflict,input.Id,state.CommitSequence,"別の操作で使ったIDです");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,input.Id,state.CommitSequence,"表示を更新してください");var prior=state;try{Change(w=>PersonalCompanions.Apply(w,input));var order=state.Companions!.Orders.Single(q=>q.Input.Id==input.Id);foreach(var task in new[]{order.Task,order.LeaderTask}.Where(i=>i!=null)){var result=Submit(task!,state.CommitSequence);if(result.Code!=ResultCode.Accepted){state=prior;return new(ResultCode.NotAvailable,input.Id,state.CommitSequence,result.VisibleReason);}}return new(ResultCode.Accepted,input.Id,state.CommitSequence,"現地で合意した協力・手当を記録しました");}catch(Exception e)when(e is InvalidDataException or ArgumentException or InvalidOperationException or OverflowException){state=prior;return new(ResultCode.NotAvailable,input.Id,state.CommitSequence,e.Message);}}}
}
